tool_input.old_string:
await page.waitForFunction(
  (count) => document.querySelectorAll('.top-nav .nav-item').length === count,
  NAV_TITLES.length,
  { timeout: 60000 }
)
await page.addStyleTag({ content: '*, *::before, *::after { animation: none !important; transition: none !important; caret-color: transparent !important; }' })

tool_input.new_string:
await page.waitForFunction(
  (count) => document.querySelectorAll('.top-nav .nav-item').length === count,
  NAV_TITLES.length,
  { timeout: 60000 }
)
const initialActive = page.locator('.top-nav .nav-item.active')
assert.equal(await initialActive.count(), 1, '工作中心 is the initial active menu')
assert.ok((await initialActive.innerText()).includes(NAV_TITLES[0]), 'active menu is 工作中心')
await page.addStyleTag({ content: '*, *::before, *::after { animation: none !important; transition: none !important; caret-color: transparent !important; }' })
